"use client"

import * as React from "react"
import { ChevronDown } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"

type ButtonGroupShape = "rounded" | "pill"
type ButtonGroupOrientation = "horizontal" | "vertical"

/** aria-orientation is only valid on these roles (WAI-ARIA 1.2); on the default
 *  role="group" it is an axe violation, so the stacking lives in data-orientation. */
const ORIENTED_ROLES = new Set(["radiogroup", "toolbar", "listbox", "menu", "menubar", "tablist", "tree", "treegrid"])

function ButtonGroup({
  shape = "rounded",
  orientation = "horizontal",
  className,
  ...props
}: React.ComponentProps<"div"> & {
  shape?: ButtonGroupShape
  /** "horizontal" puts the buttons in a row, "vertical" stacks them with shared edges. */
  orientation?: ButtonGroupOrientation
}) {
  return (
    <div
      role="group"
      data-slot="button-group"
      data-shape={shape}
      data-orientation={orientation}
      aria-orientation={orientation === "vertical" && props.role && ORIENTED_ROLES.has(props.role) ? "vertical" : undefined}
      className={cn(
        "inline-flex data-[orientation=vertical]:flex-col",
        "[&>*]:rounded-none [&>*]:focus-visible:z-10",
        // The buttons share one edge: the next one overlaps the border of the previous by 1 px.
        "data-[orientation=horizontal]:[&>*:not(:first-child)]:-ml-px data-[orientation=vertical]:[&>*:not(:first-child)]:-mt-px",
        // Only the two outer ends are rounded: left and right in a row, top and bottom in a stack.
        "data-[orientation=horizontal]:data-[shape=rounded]:[&>*:nth-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-l-md data-[orientation=horizontal]:data-[shape=rounded]:[&>*:nth-last-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-r-md",
        "data-[orientation=horizontal]:data-[shape=pill]:[&>*:nth-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-l-full data-[orientation=horizontal]:data-[shape=pill]:[&>*:nth-last-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-r-full",
        "data-[orientation=vertical]:data-[shape=rounded]:[&>*:nth-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-t-md data-[orientation=vertical]:data-[shape=rounded]:[&>*:nth-last-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-b-md",
        "data-[orientation=vertical]:data-[shape=pill]:[&>*:nth-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-t-xl data-[orientation=vertical]:data-[shape=pill]:[&>*:nth-last-child(1_of_:not([data-base-ui-focus-guard],[aria-owns]))]:rounded-b-xl",
        className
      )}
      {...props}
    />
  )
}

type SplitButtonSize = "sm" | "md" | "lg" | "xl" | "2xl"

/** Width of the menu part: as wide as the button is high (a square at every density). */
const SPLIT_MENU_WIDTH: Record<SplitButtonSize, string> = {
  sm: "w-(--control-sm)",
  md: "w-(--control-md)",
  lg: "w-(--control-lg)",
  xl: "w-(--control-xl)",
  "2xl": "w-(--control-2xl)",
}

/**
 * Button / Split has no focus ring (Owner rule 30.10.2026). Every ring class of the Button
 * is replaced, so keyboard focus shows only through the hover and pressed fills below.
 */
const SPLIT_NO_RING =
  "focus-visible:outline-none! focus-visible:outline-0! focus-visible:outline-offset-0! focus-visible:outline-transparent!"

/** Hover, pressed and open fills per part (plain: hover = bg-page, pressed and open = bg-subtle). */
const SPLIT_VARIANT: Record<"plain" | "solid", { variant: "plain" | "primary"; part: string; menu: string }> = {
  plain: {
    variant: "plain",
    part:
      "focus-visible:border-border-control! hover:bg-bg-page focus-visible:bg-bg-page active:bg-bg-subtle " +
      "active:not-aria-[haspopup]:scale-100",
    menu: "data-popup-open:bg-bg-subtle data-popup-open:hover:bg-bg-subtle",
  },
  solid: {
    variant: "primary",
    part:
      "focus-visible:border-primary! focus-visible:bg-(--brand-700) " +
      "active:not-aria-[haspopup]:scale-100",
    // The divider is white at 30 % on the primary fill, the same hue family as the label.
    menu: "border-s-primary-foreground/30 data-popup-open:bg-(--brand-800) data-popup-open:border-(color:--brand-800)",
  },
}

/** The props of the menu popup (the DropdownMenu content), without its children. */
type SplitButtonMenuProps = Omit<React.ComponentProps<typeof DropdownMenuContent>, "children">

type SplitButtonProps = Omit<React.ComponentProps<typeof Button>, "variant" | "shape" | "size" | "children" | "onClick"> & {
  /** "plain" (default) is a white button with a border, "solid" the primary fill. */
  variant?: "plain" | "solid"
  /**
   * Same sizes as the Button. The Figma "Medium 40" is `size="lg"`; the default stays the
   * Button default `md`.
   */
  size?: SplitButtonSize
  shape?: ButtonGroupShape
  /** Disables both parts. */
  disabled?: boolean
  /** The label of the action part. */
  children?: React.ReactNode
  /** Leading icon of the action part. Decorative. */
  icon?: React.ReactNode
  /** Runs when the action part is pressed. */
  onAction?: React.MouseEventHandler<HTMLButtonElement>
  /** The entries of the menu: DropdownMenuItem, DropdownMenuSeparator and so on. */
  menu?: React.ReactNode
  /** Accessible name of the menu part. Default "More actions". */
  menuLabel?: string
  /** Props for the menu popup, for example `align`. Default `align="end"`. */
  menuProps?: SplitButtonMenuProps
  /** Controlled open state of the menu. */
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Class names for the group wrapping both parts. */
  groupClassName?: string
}

/**
 * Figma: Button / Split 2574:154817 — an action part and a menu part (chevron)
 * with a divider between them. Press the action part to run the primary action;
 * the chevron opens a DropdownMenu with the alternatives.
 *
 * Each part has its own hover (plain: bg-page), pressed and open fill (plain:
 * bg-subtle; the menu part stays pressed while its menu is open). There is
 * **no focus ring** by Owner rule (30.10.2026): keyboard focus shows through
 * the hover fill. For a single button that opens a menu use
 * `DropdownMenuTrigger render={<Button />}` (that one keeps the ring).
 *
 * ```tsx
 * <SplitButton onAction={save} menu={<DropdownMenuItem>Save as draft</DropdownMenuItem>}>
 *   Save
 * </SplitButton>
 * ```
 */
function SplitButton({
  variant = "plain",
  size = "md",
  shape = "rounded",
  disabled,
  children,
  icon,
  onAction,
  menu,
  menuLabel = "More actions",
  menuProps,
  open,
  defaultOpen,
  onOpenChange,
  className,
  groupClassName,
  ...props
}: SplitButtonProps) {
  const v = SPLIT_VARIANT[variant]
  return (
    <ButtonGroup shape={shape} data-slot="split-button" data-variant={variant} className={groupClassName}>
      <Button
        data-slot="split-button-action"
        type="button"
        variant={v.variant}
        size={size}
        disabled={disabled}
        onClick={onAction}
        className={cn(SPLIT_NO_RING, v.part, className)}
        {...props}
      >
        {icon && (
          <span aria-hidden className="flex shrink-0">
            {icon}
          </span>
        )}
        {children}
      </Button>
      <DropdownMenu open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
        <DropdownMenuTrigger
          disabled={disabled}
          render={
            <Button
              data-slot="split-button-menu"
              type="button"
              variant={v.variant}
              size={size}
              aria-label={menuLabel}
              className={cn(SPLIT_NO_RING, v.part, v.menu, "px-0", SPLIT_MENU_WIDTH[size])}
            />
          }
        >
          <ChevronDown aria-hidden />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" {...menuProps}>
          {menu}
        </DropdownMenuContent>
      </DropdownMenu>
    </ButtonGroup>
  )
}

export { ButtonGroup, SplitButton }
export type { ButtonGroupOrientation, ButtonGroupShape, SplitButtonProps, SplitButtonSize }

"use client"

import * as React from "react"
import { Menu as MenuPrimitive } from "@base-ui/react/menu"
import { cn } from "@/lib/utils"
import { ChevronRightIcon, CheckIcon, MinusIcon } from "lucide-react"
import { Spinner } from "@/components/ui/spinner"

/**
 * A menu of actions: an entry does something and the menu closes. Not for
 * picking a value in a form (use Select) and not for links to pages (use a
 * disclosure such as the Navbar mega menu).
 *
 * Disabled entries stay focusable but cannot be activated (WAI-ARIA APG, and
 * what Base UI does): arrow keys still reach them, so screen reader users
 * learn the action exists.
 */
function DropdownMenu({ ...props }: MenuPrimitive.Root.Props) {
  return <MenuPrimitive.Root data-slot="dropdown-menu" {...props} />
}

function DropdownMenuPortal({ ...props }: MenuPrimitive.Portal.Props) {
  return <MenuPrimitive.Portal data-slot="dropdown-menu-portal" {...props} />
}

function DropdownMenuTrigger({ ...props }: MenuPrimitive.Trigger.Props) {
  return <MenuPrimitive.Trigger data-slot="dropdown-menu-trigger" {...props} />
}

/**
 * Motion is a transition, not a keyframe animation, so a menu closed halfway
 * through opening reverses smoothly. It grows from the trigger
 * (`--transform-origin`), slides in from the side it opened on, and closes a
 * step faster than it opens. Keyboard-opened submenus (`data-instant`) skip it.
 */
const POPUP_MOTION =
  "transition-[opacity,scale,translate] duration-fast ease-entrance motion-reduce:transition-none " +
  "data-starting-style:opacity-0 data-starting-style:scale-(--scale-enter) " +
  "data-ending-style:opacity-0 data-ending-style:scale-(--scale-enter) data-ending-style:duration-fast data-ending-style:ease-exit " +
  "data-[side=bottom]:data-starting-style:-translate-y-(--travel-sm) data-[side=top]:data-starting-style:translate-y-(--travel-sm) " +
  "data-[side=inline-end]:data-starting-style:-translate-x-(--travel-sm) data-[side=right]:data-starting-style:-translate-x-(--travel-sm) " +
  "data-[side=inline-start]:data-starting-style:translate-x-(--travel-sm) data-[side=left]:data-starting-style:translate-x-(--travel-sm) " +
  "data-closed:pointer-events-none data-instant:transition-none"

function DropdownMenuContent({
  align = "start",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  submenu = false,
  className,
  ...props
}: MenuPrimitive.Popup.Props &
  Pick<
    MenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  > & {
    /** Submenus are smaller, so they open a step faster (duration-fast). */
    submenu?: boolean
  }) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        // A menu whose trigger scrolled out of its container hides instead of floating.
        className="isolate z-50 outline-none data-anchor-hidden:invisible"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          data-slot="dropdown-menu-content"
          className={cn(
            // As wide as its longest entry (a menu, not a select); never taller than the room left.
            "z-50 [--surface:var(--popover)] max-h-[max(0px,var(--available-height))] w-max min-w-32 max-w-[min(20rem,var(--available-width))] origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-none",
            // 2 px between two entries (owner rule, 10 Nov 2026), so a hovered, focused or checked row never touches the next one.
            "[&_[role^=menuitem]+[role^=menuitem]]:mt-0.5",
            POPUP_MOTION,
            submenu ? "duration-fast shadow-lg" : "duration-base",
            className
          )}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  )
}

/**
 * Set by DropdownMenuGroup and DropdownMenuRadioGroup so a label knows whether
 * it can use Base UI's GroupLabel — which throws outside a group — or has to
 * fall back to a plain heading.
 */
const DropdownMenuGroupContext = React.createContext(false)

function DropdownMenuGroup({ children, ...props }: MenuPrimitive.Group.Props) {
  return (
    <MenuPrimitive.Group data-slot="dropdown-menu-group" {...props}>
      <DropdownMenuGroupContext.Provider value>{children}</DropdownMenuGroupContext.Provider>
    </MenuPrimitive.Group>
  )
}

const DROPDOWN_LABEL_CLASSES = "px-2 py-1.5 text-xs font-medium text-muted-foreground data-inset:ps-7"

/**
 * A section heading inside a menu. Inside a group it becomes the group's
 * accessible name; on its own it is a plain heading, so it can never crash
 * a menu that is not grouped.
 */
function DropdownMenuLabel({
  className,
  inset,
  ...props
}: MenuPrimitive.GroupLabel.Props & {
  inset?: boolean
}) {
  const inGroup = React.useContext(DropdownMenuGroupContext)
  if (!inGroup) {
    const { render: _render, ...rest } = props
    return (
      <div
        data-slot="dropdown-menu-label"
        data-inset={inset || undefined}
        className={cn(DROPDOWN_LABEL_CLASSES, typeof className === "string" ? className : undefined)}
        {...(rest as React.ComponentProps<"div">)}
      />
    )
  }
  return (
    <MenuPrimitive.GroupLabel
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn(DROPDOWN_LABEL_CLASSES, className)}
      {...props}
    />
  )
}

/**
 * Row styles shared by every entry type. The highlight moves instantly (arrow
 * keys and type-ahead are rapid-fire), and the focus highlight always wins
 * over the checked tint, so a checked entry never looks unfocusable.
 */
const ITEM_BASE =
  "relative flex cursor-default items-center gap-2 rounded-md px-2 py-(--menu-item-py) text-label-sm font-medium outline-hidden select-none " +
  "focus:bg-bg-page focus:text-foreground active:bg-bg-subtle data-inset:ps-7 " +
  "data-checked:not-focus:bg-tint-indigo data-selected:not-focus:bg-tint-indigo " +
  // Label and check of a checked entry take the tint text of the same hue (disabled keeps its grey).
  "data-checked:not-focus:not-data-disabled:text-tint-text-indigo data-selected:not-focus:not-data-disabled:text-tint-text-indigo " +
  "data-disabled:text-text-tertiary data-disabled:focus:bg-bg-page data-disabled:focus:text-text-tertiary " +
  "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4"

function DropdownMenuItem({
  className,
  inset,
  variant = "default",
  icon,
  avatar,
  description,
  children,
  ...props
}: MenuPrimitive.Item.Props & {
  inset?: boolean
  /** Destructive entries also say it in the label ("Delete project"), never by colour alone. */
  variant?: "default" | "destructive"
  /** Leading icon; decorative, hidden from assistive technology. */
  icon?: React.ReactNode
  /**
   * Leading avatar, for an entry that stands for a person or a workspace
   * (`<Avatar size="sm">…</Avatar>`, 24 px). It sits where the icon would and takes its
   * place when both are set; the row stays 32 px. Decorative, hidden from assistive
   * technology, so the label has to name the entry.
   */
  avatar?: React.ReactNode
  /** A second line under the label. The label names the entry, the line describes it. */
  description?: React.ReactNode
}) {
  const id = React.useId()
  const labelId = `${id}-label`
  const descriptionId = `${id}-description`
  return (
    <MenuPrimitive.Item
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      aria-labelledby={description ? labelId : undefined}
      aria-describedby={description ? descriptionId : undefined}
      className={cn(
        "group/dropdown-menu-item",
        ITEM_BASE,
        "not-data-[variant=destructive]:focus:**:text-accent-foreground data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive dark:data-[variant=destructive]:focus:bg-destructive/20 data-[variant=destructive]:*:[svg]:text-destructive",
        description && "items-start",
        className
      )}
      {...props}
    >
      {avatar ? (
        // A 24 px avatar in the 20 px text line: the negative margin keeps the row at 32 px.
        <span aria-hidden data-slot="dropdown-menu-item-avatar" className={cn("flex shrink-0", description ? "mt-0.5" : "-my-0.5")}>
          {avatar}
        </span>
      ) : (
        icon && (
          <span aria-hidden className={cn("flex shrink-0", description && "mt-0.5")}>
            {icon}
          </span>
        )
      )}
      {description ? (
        <>
          <span className="flex min-w-0 flex-1 flex-col gap-0.5">
            <span id={labelId}>{children}</span>
            <span id={descriptionId} className="text-xs font-normal text-text-tertiary group-focus/dropdown-menu-item:text-accent-foreground/80">
              {description}
            </span>
          </span>
        </>
      ) : (
        children
      )}
    </MenuPrimitive.Item>
  )
}

function DropdownMenuSub({ ...props }: MenuPrimitive.SubmenuRoot.Props) {
  return <MenuPrimitive.SubmenuRoot data-slot="dropdown-menu-sub" {...props} />
}

/**
 * Opens its submenu on hover after 100 ms (Base UI's safe polygon keeps it
 * open on the diagonal way over) or instantly with → / Enter.
 */
function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: MenuPrimitive.SubmenuTrigger.Props & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.SubmenuTrigger
      data-slot="dropdown-menu-sub-trigger"
      data-inset={inset}
      delay={100}
      className={cn(
        ITEM_BASE,
        "focus:**:text-accent-foreground data-popup-open:bg-bg-page data-popup-open:text-foreground",
        className
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon aria-hidden className="ms-auto rtl:rotate-180" />
    </MenuPrimitive.SubmenuTrigger>
  )
}

function DropdownMenuSubContent({
  align = "start",
  alignOffset = -5,
  side = "inline-end",
  sideOffset = 0,
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuContent>) {
  return (
    <DropdownMenuContent
      data-slot="dropdown-menu-sub-content"
      // No gap between entry and submenu: an unbridged offset is its own version of the diagonal bug.
      submenu
      className={className}
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
      {...props}
    />
  )
}

/** The check confirms instantly: opacity and scale, duration-instant. */
// keepMounted leaves the unchecked indicators in the DOM (so they can animate in): hide them while unchecked
const INDICATOR_MOTION =
  "transition-[opacity,scale] duration-instant ease-entrance motion-reduce:transition-none data-starting-style:scale-50 data-starting-style:opacity-0 data-ending-style:opacity-0 data-unchecked:scale-50 data-unchecked:opacity-0"

/**
 * A menu entry that toggles an option. Base UI only knows a boolean `checked`, so the
 * mixed state is built here: with `indeterminate` the entry reports `aria-checked="mixed"`
 * and shows a dash instead of the check (Figma: Dropdown Item, Checkbox, Mixed).
 *
 * `indeterminate` is controlled: a click still calls `onCheckedChange(true)`, the
 * entry becomes checked as soon as the parent drops `indeterminate` (for "Select all":
 * all items on, `indeterminate` off).
 */
function DropdownMenuCheckboxItem({
  className,
  children,
  checked,
  inset,
  indeterminate,
  ...props
}: MenuPrimitive.CheckboxItem.Props & {
  inset?: boolean
  /** The mixed state (some, not all). Shows a dash and `aria-checked="mixed"`; ignores `checked`. */
  indeterminate?: boolean
}) {
  return (
    <MenuPrimitive.CheckboxItem
      data-slot="dropdown-menu-checkbox-item"
      data-inset={inset}
      data-indeterminate={indeterminate ? "" : undefined}
      className={cn(ITEM_BASE, "pe-8 focus:**:text-accent-foreground", className)}
      checked={indeterminate ? false : checked}
      {...props}
      {...(indeterminate ? { "aria-checked": "mixed" as const } : null)}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute end-2 flex items-center justify-center"
        data-slot="dropdown-menu-checkbox-item-indicator"
      >
        <MenuPrimitive.CheckboxItemIndicator keepMounted className={INDICATOR_MOTION}>
          <CheckIcon />
        </MenuPrimitive.CheckboxItemIndicator>
        <MinusIcon
          data-slot="dropdown-menu-checkbox-item-mixed"
          className={cn(
            "absolute transition-[opacity,scale] duration-instant ease-entrance motion-reduce:transition-none",
            indeterminate ? "scale-100 opacity-100" : "scale-50 opacity-0"
          )}
        />
      </span>
      {children}
    </MenuPrimitive.CheckboxItem>
  )
}

function DropdownMenuRadioGroup({ children, ...props }: MenuPrimitive.RadioGroup.Props) {
  return (
    <MenuPrimitive.RadioGroup data-slot="dropdown-menu-radio-group" {...props}>
      <DropdownMenuGroupContext.Provider value>{children}</DropdownMenuGroupContext.Provider>
    </MenuPrimitive.RadioGroup>
  )
}

function DropdownMenuRadioItem({
  className,
  children,
  inset,
  ...props
}: MenuPrimitive.RadioItem.Props & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.RadioItem
      data-slot="dropdown-menu-radio-item"
      data-inset={inset}
      className={cn(ITEM_BASE, "pe-8 focus:**:text-accent-foreground", className)}
      {...props}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute end-2 flex items-center justify-center"
        data-slot="dropdown-menu-radio-item-indicator"
      >
        <MenuPrimitive.RadioItemIndicator keepMounted className={INDICATOR_MOTION}>
          <CheckIcon />
        </MenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </MenuPrimitive.RadioItem>
  )
}

function DropdownMenuSeparator({
  className,
  ...props
}: MenuPrimitive.Separator.Props) {
  return (
    <MenuPrimitive.Separator
      data-slot="dropdown-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  )
}

/**
 * The visible shortcut hint. Hidden from assistive technology so the entry is
 * named "Copy", not "Copy ⌘C"; put the machine-readable binding on the entry
 * with `aria-keyshortcuts="Meta+C"`.
 */
function DropdownMenuShortcut({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      aria-hidden
      data-slot="dropdown-menu-shortcut"
      className={cn(
        "ms-auto text-xs tracking-widest text-muted-foreground group-focus/dropdown-menu-item:text-accent-foreground",
        className
      )}
      {...props}
    />
  )
}

/**
 * Shown while the entries load. A status line, not an entry: arrow keys never
 * land on it. Set `aria-busy` on DropdownMenuContent while it is visible.
 */
function DropdownMenuLoading({ className, children = "Loading…", ...props }: React.ComponentProps<"div">) {
  return (
    <div
      role="status"
      data-slot="dropdown-menu-loading"
      className={cn("flex items-center gap-2 px-2 py-2 text-label-sm text-text-tertiary", className)}
      {...props}
    >
      <Spinner className="size-4" />
      {children}
    </div>
  )
}

/** Shown when there is nothing to act on, so the menu is never an empty dead end. */
function DropdownMenuEmpty({ className, children = "Nothing here yet", ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dropdown-menu-empty"
      className={cn("px-2 py-4 text-center text-label-sm text-text-tertiary", className)}
      {...props}
    >
      {children}
    </div>
  )
}

export {
  DropdownMenu,
  DropdownMenuPortal,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
  DropdownMenuLoading,
  DropdownMenuEmpty,
}

import * as React from "react"
import { Loader2 } from "lucide-react"
import { cn } from "@/lib/utils"

function Spinner({ className, ...props }: React.ComponentProps<"svg">) {
  return (
    <Loader2
      data-slot="spinner"
      role="status"
      aria-label="Loading"
      className={cn("size-4 animate-spin text-muted-foreground motion-reduce:animate-none", className)}
      {...props}
    />
  )
}

export { Spinner }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Check, Loader2, RotateCw } from "lucide-react"
import { cn } from "@/lib/utils"

// --primary/--brand-primary is the indigo brand color; its text uses
// --primary-foreground/--brand-primary-foreground (white), which is AA-safe
// on indigo. gradient tracks the same primary token (light tint -> primary),
// so its text reuses primary-foreground too. outline keeps a fixed white
// background independent of the primary token, so its text stays a fixed
// dark color (#25272a) rather than tracking primary-foreground, which is
// white and would fail contrast on that fixed white background.
// See /scripts/contrast-audit.mjs.
//
// Hover and pressed on the filled variants are fixed token colours, the Figma values:
// primary and brand go brand-700 on hover and brand-800 pressed (white label 7.0:1 and
// 10.0:1), destructive goes red-800 and red-900 (6.5:1 and 10.6:1), the dark button
// goes dark-400 and dark-500. They replaced brightness-95, which dimmed fill and label
// together and left the pressed state with no colour at all (only a scale). The plain
// button follows the neutral-surface rule: hover bg-page, pressed bg-subtle.
// Focus (owner rule 31 Oct 2026): the border turns indigo and a 2 px indigo-300 outline sits directly on it
// (utility focus-ring); destructive keeps its red hue (focus-ring-error) and the dark button, whose border is
// its fill, gets a dark-300 ring. The gradient hover and pressed states are brand-600/700 and 700/800 stops.
//
// The gradient top stop was #6f74f5, which put the top edge of the button at
// 3.82:1 -- the gradient, not the token, was the failure. #5a5ef4 keeps a
// visible sheen (4.84:1 top, 4.99:1 bottom) and the inset white highlight
// carries the rest of the raised look. Its hover brightened (brightness-105,
// 3.52:1); it now darkens like the other filled variants (4.71:1 top).
const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center gap-2 border border-transparent text-sm font-medium whitespace-nowrap transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:not-aria-[haspopup]:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-bg-page data-popup-open:bg-bg-page active:bg-bg-subtle focus-ring",
        primary:
          "border-primary bg-primary text-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        gradient:
          "border-primary bg-gradient-to-b from-[#5a5ef4] to-primary text-primary-foreground shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05),inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:from-(--brand-600) hover:to-(--brand-700) active:from-(--brand-700) active:to-(--brand-800) focus-ring",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white active:bg-(--dark-500) active:text-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--dark-300)",
        light: "bg-white bg-clip-padding text-primary hover:bg-(--light-200) focus-ring",
        // Figma Type=blue_outline: indigo rim, link-coloured label, indigo tint on hover.
        outline: "bg-card border-primary text-text-link hover:border-tint-text-indigo hover:bg-tint-indigo hover:text-tint-text-indigo active:bg-bg-subtle active:text-tint-text-indigo focus-ring",
        // Indigo tint: the selected-option look of the button group and segmented selectors.
        tint: "bg-tint-indigo text-tint-text-indigo focus-ring",
        // Figma Type=ghost / destructive / link (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-bg-page data-popup-open:bg-bg-page active:bg-bg-subtle focus-ring",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:border-red-800 hover:bg-red-800 active:border-red-900 active:bg-red-900 focus-ring-error",
        link: "bg-transparent px-0! text-text-link shadow-none underline-offset-4 hover:text-text-link-hover hover:underline active:text-text-link-pressed focus-ring",
      },
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        // Heights and paddings are density tokens (styles.css): compact 32/36/40/44/48,
        // data-density="comfortable" 36/40/44/48/56. The icon side sits 2 px tighter (2xl 4 px).
        sm: "h-(--control-sm) px-(--control-px-sm) text-sm has-data-[icon=inline-end]:pr-[calc(var(--control-px-sm)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-sm)-0.125rem)]",
        // Icon sizes follow the Figma Button sets: Small and Regular 16 px, Medium 20 px, Large and Xlarge 24 px. Heights and paddings are unchanged.
        md: "h-(--control-md) px-(--control-px-md) text-sm has-data-[icon=inline-end]:pr-[calc(var(--control-px-md)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-md)-0.125rem)]",
        lg: "h-(--control-lg) px-(--control-px-lg) text-sm [&_svg:not([class*='size-'])]:size-5 has-data-[icon=inline-end]:pr-[calc(var(--control-px-lg)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-lg)-0.125rem)]",
        xl: "h-(--control-xl) px-(--control-px-xl) text-base [&_svg:not([class*='size-'])]:size-6 has-data-[icon=inline-end]:pr-[calc(var(--control-px-xl)-0.125rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-xl)-0.125rem)]",
        "2xl": "h-(--control-2xl) px-(--control-px-2xl) text-lg [&_svg:not([class*='size-'])]:size-6 has-data-[icon=inline-end]:pr-[calc(var(--control-px-2xl)-0.25rem)] has-data-[icon=inline-start]:pl-[calc(var(--control-px-2xl)-0.25rem)]",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

type ButtonPhase = "idle" | "pending" | "success" | "error"

function Button({
  className,
  variant,
  shape,
  size,
  children,
  onClick,
  pending,
  phase,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof buttonVariants> & {
    /**
     * Shows a spinner in place of the leading icon and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback: pending shows a spinner, success a check, error a retry
     * icon. The label is yours (for example Saving…, Saved, Retry). Keep the
     * width constant with a fixed width on the button so it does not jump
     * between phases.
     */
    phase?: ButtonPhase
  }) {
  const status: ButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" &&
    ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const filteredChildren = React.Children.toArray(children).filter((child) => {
    if (!React.isValidElement<{ "data-icon"?: string }>(child)) {
      return true
    }
    return child.props["data-icon"] !== "inline-start"
  })

  const quiet = ["plain", "ghost", "outline", "tint"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Loader2
        aria-hidden
        data-icon="inline-start"
        className="animate-spin motion-reduce:animate-none"
      />
    )
  } else if (status === "success") {
    statusIcon = (
      <Check
        aria-hidden
        data-icon="inline-start"
        strokeWidth={1.5}
        className={quiet ? "text-text-success" : undefined}
      />
    )
  } else if (status === "error") {
    statusIcon = (
      <RotateCw
        aria-hidden
        data-icon="inline-start"
        strokeWidth={1.5}
        className={quiet ? "text-text-error" : undefined}
      />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(
        buttonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className })
      )}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? null : statusIcon}
      {isIdle ? children : filteredChildren}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }
export type { ButtonPhase }
